/** The link colours of D52 for LinkAnnotation: the word in text, link while pressed or under the pointer. */
@Composable
fun sbLinkStyles(): TextLinkStyles {
    val c = SebaroTheme.colors
    return TextLinkStyles(
        style = SpanStyle(color = c.text),
        hoveredStyle = SpanStyle(color = c.link),
        pressedStyle = SpanStyle(color = c.link),
    )
}

/**
 * A word with the link underline (SbTextAction): 2 dp in link at the bottom of the text. [layout] = the text's last
 * layout (its onTextLayout): a text that wraps gets the underline under each of its lines, from the line's start to
 * its end (D99 (1): a text action whose word wraps at large text); one line, or no layout, draws it across the width.
 */
@Composable
fun Modifier.sbLinkUnderline(layout: () -> TextLayoutResult? = { null }): Modifier {
    val c = SebaroTheme.colors
    val width = SebaroTheme.tokens.x.linkUnderlineWidth
    return drawBehind {
        val w = width.toPx()
        val l = layout()
        if (l == null || l.lineCount <= 1) {
            val y = size.height - w / 2f
            drawLine(c.link, Offset(0f, y), Offset(size.width, y), w)
        } else {
            for (line in 0 until l.lineCount) {
                val y = l.getLineBottom(line) - w / 2f
                drawLine(c.link, Offset(l.getLineLeft(line), y), Offset(l.getLineRight(line), y), w)
            }
        }
    }
}

/** Running text whose LinkAnnotation ranges get the 2 dp link underline (D52); everything else is plain text. */
@Composable
fun SbLinkText(text: AnnotatedString, modifier: Modifier = Modifier, style: TextStyle = SebaroTheme.typography.body) {
    val c = SebaroTheme.colors
    val width = SebaroTheme.tokens.x.linkUnderlineWidth
    var layout by remember { mutableStateOf<TextLayoutResult?>(null) }
    Text(
        text,
        modifier.drawBehind {
            val l = layout ?: return@drawBehind
            val w = width.toPx()
            val gap = style.fontSize.toPx() * 0.2f
            text.getLinkAnnotations(0, text.length).forEach { range ->
                for (line in l.getLineForOffset(range.start)..l.getLineForOffset(range.end - 1)) {
                    val from = maxOf(range.start, l.getLineStart(line))
                    val to = minOf(range.end, l.getLineEnd(line, visibleEnd = true))
                    if (from >= to) continue
                    val x1 = l.getHorizontalPosition(from, usePrimaryDirection = true)
                    val x2 = l.getHorizontalPosition(to, usePrimaryDirection = true)
                    val y = l.getLineBaseline(line) + gap
                    drawLine(c.link, Offset(minOf(x1, x2), y), Offset(maxOf(x1, x2), y), w)
                }
            }
        },
        style = style,
        color = c.text,
        onTextLayout = { layout = it },
    )
}
